# =============================================================================
# Part 2: annotate significant fGSEA pathways with biological themes
# =============================================================================

annotate_gsea_themes <- function(
    df,
    theme_dict,
    pathway_col = "pathway"
) {
  
  required_cols <- c(
    pathway_col,
    "NES",
    "p_adj"
  )
  
  missing_cols <- setdiff(
    required_cols,
    colnames(df)
  )
  
  if (length(missing_cols) > 0) {
    stop(
      "Missing required columns: ",
      paste(
        missing_cols,
        collapse = ", "
      )
    )
  }
  
  df2 <- df %>%
    tibble::as_tibble() %>%
    dplyr::mutate(
      .row_id = dplyr::row_number()
    )
  
  dict_long <- tibble::enframe(
    theme_dict,
    name = "theme",
    value = "keyword"
  ) %>%
    tidyr::unnest_longer(keyword) %>%
    dplyr::mutate(
      keyword = as.character(keyword)
    )
  
  # Cartesian join followed by keyword matching.
  # A pathway can match more than one biological theme.
  matches <- df2 %>%
    dplyr::select(
      .row_id,
      dplyr::all_of(pathway_col)
    ) %>%
    tidyr::crossing(
      dict_long
    ) %>%
    dplyr::mutate(
      .matched = stringr::str_detect(
        .data[[pathway_col]],
        stringr::regex(
          keyword,
          ignore_case = TRUE
        )
      )
    ) %>%
    dplyr::filter(
      .matched
    ) %>%
    dplyr::transmute(
      .row_id,
      theme,
      matched_keyword = keyword
    )
  
  # Keep unmatched pathways with NA theme/keyword.
  df2 %>%
    dplyr::left_join(
      matches,
      by = ".row_id"
    ) %>%
    dplyr::select(
      -.row_id
    )
}


# -----------------------------------------------------------------------------
# Read significant pathways from fGSEA outputs generated by scripts 08 and 09
#
# In the original working script, significant pathway names, NES values and
# adjusted P values were copied into R data.frames before theme annotation.
# Here the same information is read directly from the deposited fGSEA outputs.
# -----------------------------------------------------------------------------

fgsea_files <- c(
  
  CCl4_heps =
    "CCl4vsControl_hepatocytes_fgsea.csv",
  
  CCl4_endo =
    "CCl4vsControl_endo_fgsea.csv",
  
  CCl4_macro =
    "CCl4vsControl_macro_fgsea.csv",
  
  CCl4_hsc =
    "CCl4vsControl_hsc_fgsea.csv",
  
  DEN_heps =
    "DENvsControl_hepatocytes_fgsea.csv",
  
  DEN_endo =
    "DENvsControl_endo_fgsea.csv",
  
  DEN_macro =
    "DENvsControl_macro_fgsea.csv",
  
  DEN_hsc =
    "DENvsControl_hsc_fgsea.csv",
  
  models_heps =
    "DENvsCCl4_hepatocytes_fgsea.csv",
  
  models_endo =
    "DENvsCCl4_endo_fgsea.csv",
  
  models_macro =
    "DENvsCCl4_macro_fgsea.csv",
  
  models_hsc =
    "DENvsCCl4_hsc_fgsea.csv",
  
  models_tumorCells =
    "DENvsCCl4_malignantHeps_fgsea.csv"
)


collapsed_results <- list()

for (nm in names(fgsea_files)) {
  
  fg <- readr::read_csv(
    fgsea_files[[nm]],
    show_col_types = FALSE
  ) %>%
    dplyr::filter(
      !is.na(padj),
      padj < 0.05
    ) %>%
    dplyr::transmute(
      pathway = pathway,
      NES = NES,
      p_adj = padj
    )
  
  annotated_df <- annotate_gsea_themes(
    df = fg,
    theme_dict = theme_dict
  )
  
  collapsed_results[[nm]] <- annotated_df
  
  write.table(
    annotated_df,
    file = paste0(
      "fgsea_",
      nm,
      "_collapsed.txt"
    ),
    row.names = FALSE,
    sep = "\t",
    quote = FALSE
  )
}


