models_mat[models_mat == 0] <- NA

CCl4_direction[CCl4_direction == "0"] <- NA
DEN_direction[DEN_direction == "0"] <- NA
models_direction[models_direction == "0"] <- NA


# =============================================================================
# Part 4: prepare shared-lineage plotting data
# =============================================================================

prepare_theme_plot_data <- function(
    nes_table,
    direction_table
) {
  
  nes_long <- nes_table %>%
    dplyr::mutate(
      Theme = factor(
        Theme,
        levels = theme_order
      )
    ) %>%
    tidyr::pivot_longer(
      cols = dplyr::all_of(cell_order),
      names_to = "CellType",
      values_to = "NES"
    ) %>%
    dplyr::filter(
      !is.na(NES)
    ) %>%
    dplyr::mutate(
      CellType = factor(
        CellType,
        levels = cell_order
      ),
      absNES = abs(NES)
    )
  
  direction_long <- direction_table %>%
    tidyr::pivot_longer(
      cols = dplyr::all_of(cell_order),
      names_to = "CellType",
      values_to = "Direction"
    )
  
  nes_long %>%
    dplyr::left_join(
      direction_long,
      by = c(
        "Theme",
        "CellType"
      )
    ) %>%
    dplyr::mutate(
      Theme = factor(
        Theme,
        levels = theme_order
      ),
      CellType = factor(
        CellType,
        levels = cell_order
      )
    )
}


CCl4_long <- prepare_theme_plot_data(
  CCl4_mat,
  CCl4_direction
)

DEN_long <- prepare_theme_plot_data(
  DEN_mat,
  DEN_direction
)

models_long <- prepare_theme_plot_data(
  models_mat,
  models_direction
)


# =============================================================================
# Part 5: shared-lineage theme dot plots
# =============================================================================

plot_theme_summary <- function(
    df,
    title
) {
  
  ggplot2::ggplot(
    df,
    ggplot2::aes(
      x = CellType,
      y = Theme
    )
  ) +
    ggplot2::geom_point(
      ggplot2::aes(
        size = absNES,
        color = Direction
      ),
      alpha = 0.95
    ) +
    ggplot2::scale_color_manual(
      values = c(
        "up" = "red",
        "down" = "blue",
        "mostly up" = "orange",
        "mostly down" = "purple"
      ),
      name = NULL
    ) +
    ggplot2::scale_y_discrete(
      drop = FALSE
    ) +
    ggplot2::scale_size_continuous(
      limits = c(1, 4),
      range = c(2, 9),
      breaks = c(
        1.5,
        2,
        2.5,
        3
      ),
      name = "|NES|"
    ) +
    ggplot2::labs(
      title = title,
      x = NULL,
      y = NULL
    ) +
    ggplot2::theme_minimal(
      base_size = 12
    ) +
    ggplot2::theme(
      panel.grid.major =
        ggplot2::element_line(
          linewidth = 0.25
        ),
      panel.grid.minor =
        ggplot2::element_blank(),
      axis.text.x =
        ggplot2::element_text(
          angle = 35,
          hjust = 1
        ),
      plot.title =
        ggplot2::element_text(
          face = "bold"
        ),
      legend.position = "right"
    )
}


# Original working plot titles retained.
p_CCl4 <- plot_theme_summary(
  CCl4_long,
  "CCl4"
)

p_DEN <- plot_theme_summary(
  DEN_long,
  "DEN"
)

p_models <- plot_theme_summary(
  models_long,
  "models"
)

p_CCl4
p_DEN
p_models


